        for (int i = 0; i < nums.length; i++) {
            if (visited[i]) continue;
            visited[i] = true;
            path.add(nums[i]);
            backtrack(nums, path, visited, res);
            path.remove(path.size() - 1);
            visited[i] = false;
        }
    }
